package com.ouyunc.message.processor.http.push.delivery;import com.ouyunc.base.constant.MessageConstant;import com.ouyunc.base.constant.enums.ExceptionCodeEnum;import com.ouyunc.base.constant.enums.MessageTypeEnum;import com.ouyunc.repository.cs.CsImSessionRoute;import com.ouyunc.base.packet.Packet;import com.ouyunc.base.packet.message.Message;import com.ouyunc.message.helper.CsMessageDeliveryRouteHelper;import com.ouyunc.message.helper.CsCustomerServiceLastMessageHelper;import com.ouyunc.message.helper.CsSessionMessageHelper;import com.ouyunc.message.helper.CsSessionMessageHelper.PrepareOutcome;import com.ouyunc.message.helper.MessageRefHelper;import com.ouyunc.repository.DefaultRepository;import org.apache.commons.lang3.StringUtils;import org.slf4j.Logger;import org.slf4j.LoggerFactory;/** * HTTP 推送：客服会话投递（ticket 消息 scope）。 */public enum CsHttpPushDeliveryStrategy implements HttpProcessor {    INSTANCE;    private static final Logger log = LoggerFactory.getLogger(CsHttpPushDeliveryStrategy.class);    @Override    public MessageTypeEnum messageType() {        return MessageTypeEnum.CUSTOMER_SERVICE;    }    @Override    public void process(Packet packet) {        if (!MessageRefHelper.normalizeMessageRefOrReject(packet)) {            return;        }        Message message = packet.getMessage();        if (message == null || StringUtils.isAnyBlank(message.getFrom(), message.getTo())                || StringUtils.equals(message.getFrom(), message.getTo())) {            log.warn("HTTP 推送客服消息 from/to 无效, packetId={}", packet.getPacketId());            HttpPushDeliverySupport.publishException(ExceptionCodeEnum.CS_SESSION_ROUTE_ERROR, "from/to 无效", packet);            return;        }        PrepareOutcome prepared = CsSessionMessageHelper.prepare(packet);        if (!prepared.accepted()) {            log.warn("HTTP 推送客服路由校验失败: {}", prepared.rejectReason());            HttpPushDeliverySupport.publishException(ExceptionCodeEnum.CS_SESSION_ROUTE_ERROR, prepared.rejectReason(), packet);            return;        }        CsImSessionRoute route = prepared.route();        DefaultRepository.INSTANCE.reactiveSaveCsTicketMessage(packet, route,                        MessageConstant.CACHE_MESSAGE_HOT_KEY_EXPIRE_TIMESTAMP)                .subscribe(                        saved -> {                            if (!Boolean.TRUE.equals(saved)) {                                log.error("HTTP 推送客服消息落库失败: {}", packet);                                HttpPushDeliverySupport.publishException(ExceptionCodeEnum.CACHE_PERSISTENCE_ERROR,                                        "客服消息写入 ticket 失败", packet);                                return;                            }                            CsCustomerServiceLastMessageHelper.saveChatLastMessage(                                    DefaultRepository.INSTANCE, route, packet);                            DefaultRepository.INSTANCE.reactiveAdvanceCsSenderReadOffsetOnSend(                                            packet, route, packet.getDeviceType(),                                            MessageConstant.CACHE_MESSAGE_READ_RECEIPT_KEY_EXPIRE_TIMESTAMP)                                    .subscribe(ignored -> { }, e -> log.warn(                                            "HTTP 推送更新客服 ticket 已读 offset 失败, packetId={}", packet.getPacketId(), e));                            CsMessageDeliveryRouteHelper.deliverCustomerServiceMessage(packet, route, false);                        },                        error -> {                            log.error("HTTP 推送客服落库异常, packetId={}", packet.getPacketId(), error);                            HttpPushDeliverySupport.publishException(ExceptionCodeEnum.CACHE_PERSISTENCE_ERROR,                                    "客服持久化异常: " + error.getMessage(), packet);                        });    }}